changeSet.sql:
CREATE INDEX IF NOT EXISTS flow_ts_idx           ON flow (flow_ts);
CREATE INDEX IF NOT EXISTS flow_application_idx  ON flow (application);
CREATE INDEX IF NOT EXISTS flow_convo_key_idx    ON flow (convo_key);
CREATE INDEX IF NOT EXISTS flow_exporter_idx     ON flow (exporter_node_id);

-- Drop the legacy two-argument (retention_days, premake_days) signature, replaced below.
DROP FUNCTION IF EXISTS flow_maintain_partitions(int, int);

CREATE OR REPLACE FUNCTION flow_maintain_partitions(parent      text,
                                                    control     text,
                                                    granularity text,
                                                    retention   interval,
                                                    premake     int)
RETURNS void AS $$
DECLARE
    step        interval;
    fmt         text;
    bucket      timestamptz;
    part_name   text;
    cutoff      timestamptz := now() - retention;
    child       record;
    upper_txt   text;
    upper_bound timestamptz;
BEGIN
    -- No-op if the parent table does not exist (e.g. flow_agg before aggregation is installed).
    IF NOT EXISTS (SELECT 1 FROM pg_class WHERE relname = parent AND relkind = 'p') THEN
        RETURN;
    END IF;

    IF granularity NOT IN ('hour', 'day', 'week', 'month') THEN
        RAISE EXCEPTION 'flow_maintain_partitions: unsupported granularity % (use hour|day|week|month)', granularity;
    END IF;
    step := ('1 ' || granularity)::interval;
    fmt  := CASE granularity
                WHEN 'hour'  THEN '"p"YYYYMMDD"h"HH24'
                WHEN 'day'   THEN '"p"YYYYMMDD'
                WHEN 'week'  THEN '"p"IYYY"w"IW'
                WHEN 'month' THEN '"p"YYYYMM'
            END;

    -- Pre-create the current + `premake` future buckets.
    FOR i IN 0..premake LOOP
        bucket    := date_trunc(granularity, now()) + (i * step);
        part_name := parent || '_' || to_char(bucket, fmt);
        IF NOT EXISTS (SELECT 1 FROM pg_class WHERE relname = part_name) THEN
            BEGIN
                EXECUTE format('CREATE TABLE %I PARTITION OF %I FOR VALUES FROM (%L) TO (%L)',
                               part_name, parent, bucket, bucket + step);
            EXCEPTION WHEN others THEN
                -- Overlapping/pre-existing range (e.g. a coarser legacy partition still covers it).
                RAISE NOTICE 'flow_maintain_partitions: could not create %: %', part_name, SQLERRM;
            END;
        END IF;
    END LOOP;

    -- Drop partitions whose entire range is older than the retention cutoff.
    FOR child IN
        SELECT c.oid, c.relname, pg_get_expr(c.relpartbound, c.oid) AS bound
        FROM pg_inherits i
        JOIN pg_class c ON c.oid = i.inhrelid
        JOIN pg_class p ON p.oid = i.inhparent
        WHERE p.relname = parent
    LOOP
        -- Upper bound of a range partition: FOR VALUES FROM (...) TO ('<ts>'); DEFAULT has no match.
        upper_txt := (regexp_match(child.bound, 'TO \(''([^'']+)''\)'))[1];
        CONTINUE WHEN upper_txt IS NULL;
        upper_bound := upper_txt::timestamptz;
        IF upper_bound <= cutoff THEN
            EXECUTE format('DROP TABLE IF EXISTS %I', child.relname);
        END IF;
    END LOOP;
END;
$$ LANGUAGE plpgsql;

CREATE TABLE IF NOT EXISTS flow_agg_default PARTITION OF flow_agg DEFAULT;
CREATE INDEX IF NOT EXISTS flow_agg_window_idx ON flow_agg (window_start);
CREATE INDEX IF NOT EXISTS flow_agg_lookup_idx ON flow_agg (exporter_node_id, if_index, dimension, window_start);
SELECT flow_maintain_partitions('flow_agg', 'window_start', 'week', '6 months'::interval, 2);
